// Audio stays on this device; only model files are downloaded from Hugging Face.
let speechWorker=null,speechSequence=Promise.resolve(),speechJobs=new Map(),speechTargets=new Map(),speechCallbacks=new Map(),speechWarm=false;
function speechEnabled(){try{return localStorage.getItem('pasteinn-transcription')!=='off'}catch{return true}}
function speechClient(){if(speechWorker)return speechWorker;speechWorker=new Worker('speech-worker.mjs',{type:'module'});speechWorker.onmessage=({data})=>{if(data.kind==='progress'&&!speechWarm){$('speech-status').hidden=false;$('speech-status').textContent='Getting the local speech model… '+data.percent+'%'}if(data.kind==='ready'){speechWarm=true;if(!speechJobs.size&&!recording)$('speech-status').hidden=true}if(data.kind==='result'||data.kind==='error'){const callback=speechCallbacks.get(data.id);speechCallbacks.delete(data.id);if(callback)data.kind==='result'?callback.resolve(data.text):callback.reject(Error(data.message))}};speechWorker.onerror=()=>{for(const cb of speechCallbacks.values())cb.reject(Error('Local speech model could not load.'));speechCallbacks.clear();speechWorker?.terminate();speechWorker=null;speechWarm=false};return speechWorker}
async function speechAudio(blob){const Context=window.AudioContext||window.webkitAudioContext;if(!Context)throw Error('Audio decoding is unavailable.');const context=new Context();try{const decoded=await context.decodeAudioData(await blob.arrayBuffer());if(decoded.duration>301)throw Error('Use audio under five minutes for transcription.');const offline=new OfflineAudioContext(1,Math.max(1,Math.ceil(decoded.duration*16000)),16000),source=offline.createBufferSource();source.buffer=decoded;source.connect(offline.destination);source.start();return (await offline.startRendering()).getChannelData(0)}finally{await context.close()}}
function renderPendingTranscript(){const audio=pendingImages.filter(f=>f.blob?.type.startsWith('audio/'));$('pending-transcript').hidden=!audio.length;$('pending-transcript').innerHTML=audio.map(f=>`<div class="voice-transcript"><span>${esc(f.transcript?'Transcript':f.speechState==='working'?'Transcribing on this device…':f.speechState==='failed'?'Couldn’t transcribe.':speechEnabled()?'Waiting to transcribe…':'Transcription off')}</span>${f.transcript?`<p>${esc(f.transcript)}</p>`:''}${f.speechState==='failed'?`<button type="button" data-retry-speech="${f.id}">Try again</button>`:''}</div>`).join('')}
function trackPendingTranscripts(record){for(const file of record.media||[])if(file.blob?.type.startsWith('audio/'))speechTargets.set(file.id,record.id)}
async function retainTranscript(file,text,state){file.transcript=text;file.speechState=state;const target=speechTargets.get(file.id);if(target){const latest=notes.find(r=>r.id===target);if(latest){const media=latest.media.map(f=>f.id===file.id?{...f,transcript:text,speechState:state}:f),next={...latest,media,transcript:media.map(f=>f.transcript||'').filter(Boolean).join('\n\n')};await storeSave(next);notes=notes.map(r=>r.id===next.id?next:r);render();notifyLocalChange();if(activeSaveId===next.id)refreshDetail(next)}}renderPendingTranscript()}
function enqueueSpeech(file){if(!speechEnabled()||speechJobs.has(file.id)||file.transcript)return;file.speechState='working';speechJobs.set(file.id,file);renderPendingTranscript();$('speech-status').hidden=false;$('speech-status').textContent=speechWarm?'Transcribing on this device…':'Getting the local speech model…';speechSequence=speechSequence.then(async()=>{try{const audio=await speechAudio(file.blob),text=await new Promise((resolve,reject)=>{speechCallbacks.set(file.id,{resolve,reject});speechClient().postMessage({kind:'transcribe',id:file.id,audio},[audio.buffer])});await retainTranscript(file,text,'done')}catch(error){await retainTranscript(file,'','failed');toast('Voice kept. Transcription unavailable; you can retry in info.');}finally{speechJobs.delete(file.id);if(!speechJobs.size){$('speech-status').hidden=true;renderPendingTranscript()}}}).catch(()=>{})}
const attachFiles=addImages;addImages=async function(files){const before=new Set(pendingImages.map(f=>f.id));await attachFiles(files);for(const file of pendingImages)if(!before.has(file.id)&&file.blob.type.startsWith('audio/'))enqueueSpeech(file);renderPendingTranscript()};
$('pending-transcript').onclick=e=>{const b=e.target.closest('[data-retry-speech]');if(b){const file=pendingImages.find(f=>f.id===b.dataset.retrySpeech);if(file)enqueueSpeech(file)}};
$('retry-transcript').onclick=()=>{const r=notes.find(r=>r.id===activeSaveId);if(r)for(const file of r.media||[])if(file.blob?.type.startsWith('audio/')){speechTargets.set(file.id,r.id);enqueueSpeech(file)}};
const speechRefresh=refreshDetail;refreshDetail=function(record){speechRefresh(record);$('retry-transcript').hidden=!record?.media?.some(f=>f.blob?.type.startsWith('audio/'))||record?.media?.every(f=>!!f.transcript);};
$('transcription-enabled').checked=speechEnabled();$('transcription-enabled').onchange=e=>{try{localStorage.setItem('pasteinn-transcription',e.target.checked?'on':'off');if(e.target.checked)for(const f of pendingImages)if(f.blob?.type.startsWith('audio/'))enqueueSpeech(f);renderPendingTranscript()}catch{toast('Couldn’t save transcription preference.')}};
$('record-voice').onclick=async()=>{if(recording){recording.stop();return}try{recordingStream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks=[];recording=new MediaRecorder(recordingStream);const recorder=recording;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=()=>{recordingStream?.getTracks().forEach(t=>t.stop());recordingStream=null;recording=null;$('record-voice').classList.remove('recording');$('record-voice').setAttribute('aria-label','Record voice');$('recording-status').hidden=true;const mime=recorder.mimeType||'audio/webm';addImages([new File(chunks,`Voice note ${new Date().toISOString().slice(0,19).replace(/:/g,'-')}.${mime.includes('mp4')?'m4a':'webm'}`,{type:mime})]);};recorder.onerror=()=>{toast('Recording failed. Please try again.');if(recorder.state!=='inactive')recorder.stop()};recorder.start();$('record-voice').classList.add('recording');$('record-voice').setAttribute('aria-label','Stop recording');$('recording-status').hidden=false;if(speechEnabled()){try{speechClient().postMessage({kind:'warm'})}catch{}}setTimeout(()=>{if(recording===recorder&&recorder.state==='recording'){recorder.stop();toast('Five-minute limit reached. Your voice is attached.')}},5*60*1000);}catch{recordingStream?.getTracks().forEach(t=>t.stop());recordingStream=null;recording=null;toast('Microphone unavailable. Check permission, or attach an audio file.')}};

// Resume unfinished local work after a reload; downloaded models use their browser cache.
allLocalRecords().then(records=>{for(const r of records)if(!r.deleted)for(const f of r.media||[])if(f.blob?.type.startsWith('audio/')&&['working','pending'].includes(f.speechState)){speechTargets.set(f.id,r.id);enqueueSpeech(f)}}).catch(()=>{});
